INSERT INTO sisauto."7_evidencias" VALUES ('IQA', NULL, NULL, NULL, NULL, NULL, NULL, 'IQA - Cenário da Qualidade Automotiva no Brasil 2026-2028 (PDF)', 'Estudo qualitativo (36 entidades); não é amostra estatística; sem ROI, CAPEX ou ocupações.', NULL, NULL, NULL, 12, 'Mão de obra', 'A transição tecnológica pede profissionais atualizados em software, eletrônica veicular, IA e cibersegurança; qualificação técnica é eixo estratégico.', NULL);
INSERT INTO sisauto."7_evidencias" VALUES ('IQA', NULL, NULL, NULL, NULL, NULL, NULL, 'IQA - Cenário da Qualidade Automotiva no Brasil 2026-2028 (PDF)', 'Estudo qualitativo (36 entidades); não é amostra estatística; sem ROI, CAPEX ou ocupações.', NULL, NULL, NULL, 13, 'Escassez de profissionais', 'Falta mão de obra pronta para eletrônica embarcada, software automotivo, propulsão avançada, metrologia e processos de qualidade; gera retrabalho e dependência de treinamento contínuo.', NULL);
INSERT INTO sisauto."7_evidencias" VALUES ('IQA', NULL, NULL, NULL, NULL, NULL, NULL, 'IQA - Cenário da Qualidade Automotiva no Brasil 2026-2028 (PDF)', 'Estudo qualitativo (36 entidades); não é amostra estatística; sem ROI, CAPEX ou ocupações.', NULL, NULL, NULL, 13, 'Defasagem da formação', 'Currículos técnicos e universitários não acompanham a velocidade da transformação (eletrificação, ADAS, qualidade orientada por dados).', NULL);
INSERT INTO sisauto."7_evidencias" VALUES ('IQA', NULL, NULL, NULL, NULL, NULL, NULL, 'IQA - Cenário da Qualidade Automotiva no Brasil 2026-2028 (PDF)', 'Estudo qualitativo (36 entidades); não é amostra estatística; sem ROI, CAPEX ou ocupações.', NULL, NULL, NULL, 32, 'Macrotendências até 2035', 'Ranking de relevância: pressão por competitividade e inteligência artificial empatadas em 1º/2º; educação e qualificação em 4º.', 'IA 4,2; competitividade 4,2; qualificação 4,1 (escala 0 a 5)');
INSERT INTO sisauto."7_evidencias" VALUES ('IQA', NULL, NULL, NULL, NULL, NULL, NULL, 'IQA - Cenário da Qualidade Automotiva no Brasil 2026-2028 (PDF)', 'Estudo qualitativo (36 entidades); não é amostra estatística; sem ROI, CAPEX ou ocupações.', NULL, NULL, NULL, 48, 'Desafios na formação', 'Escassez de profissionais e defasagem da formação universitária lideram os desafios apontados.', '37% (escassez) e 30% (defasagem)');
INSERT INTO sisauto."7_evidencias" VALUES ('IQA', NULL, NULL, NULL, NULL, NULL, NULL, 'IQA - Cenário da Qualidade Automotiva no Brasil 2026-2028 (PDF)', 'Estudo qualitativo (36 entidades); não é amostra estatística; sem ROI, CAPEX ou ocupações.', NULL, NULL, NULL, 48, 'Oportunidades na formação', 'Qualificação em tecnologias emergentes é a oportunidade mais citada.', '35%');
